import { Download, Search, X } from 'lucide-react';
import { useState } from 'react';

import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';
import { cn } from '@/utils/cn';

import { useUsers } from '../api/get-users';
import { exportUsersToCsv } from '../utils/export-users';

import { DeleteUser } from './delete-user';

type RoleOption = {
  label: string;
  value: string;
};

const roleOptions: RoleOption[] = [
  { label: 'All Roles', value: '' },
  { label: 'Admin', value: 'ADMIN' },
  { label: 'User', value: 'USER' },
];

export const UsersList = () => {
  const [role, setRole] = useState<string>('');
  const [search, setSearch] = useState<string>('');

  const usersQuery = useUsers({ params: role || search ? { role, search } : undefined });

  const filteredUsers = usersQuery.data?.data
    ? usersQuery.data.data.filter((user) => {
        const matchesRole = !role || user.role === role;
        const matchesSearch =
          !search ||
          user.firstName.toLowerCase().includes(search.toLowerCase()) ||
          user.lastName.toLowerCase().includes(search.toLowerCase()) ||
          user.email.toLowerCase().includes(search.toLowerCase());
        return matchesRole && matchesSearch;
      })
    : [];

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  if (!usersQuery.data?.data) return null;

  const hasFilters = role || search;

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-gray-400" />
          <input
            type="text"
            placeholder="Search by name or email"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className={cn(
              'h-9 w-full rounded-md border border-input bg-transparent pl-9 pr-3 text-sm shadow-sm transition-colors placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring',
            )}
          />
        </div>
        <select
          value={role}
          onChange={(e) => setRole(e.target.value)}
          className="h-9 rounded-md border border-input bg-transparent px-3 text-sm shadow-sm focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
        >
          {roleOptions.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
        {hasFilters && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              setRole('');
              setSearch('');
            }}
          >
            <X className="size-4" />
            <span>Clear</span>
          </Button>
        )}
        <Button
          variant="outline"
          size="sm"
          icon={<Download className="size-4" />}
          onClick={() => exportUsersToCsv(filteredUsers)}
        >
          Export CSV
        </Button>
      </div>
      <Table
        data={filteredUsers}
        columns={[
          {
            title: 'First Name',
            field: 'firstName',
          },
          {
            title: 'Last Name',
            field: 'lastName',
          },
          {
            title: 'Email',
            field: 'email',
          },
          {
            title: 'Role',
            field: 'role',
          },
          {
            title: 'Created At',
            field: 'createdAt',
            Cell({ entry: { createdAt } }) {
              return <span>{formatDate(createdAt)}</span>;
            },
          },
          {
            title: '',
            field: 'id',
            Cell({ entry: { id } }) {
              return <DeleteUser id={id} />;
            },
          },
        ]}
      />
    </div>
  );
};

import { User } from '@/types/api';
import { formatDate } from '@/utils/format';

export const exportUsersToCsv = (users: User[]) => {
  const header = 'Name,Email,Role,Joined';
  const rows = users.map((user) => {
    const name = `"${user.firstName} ${user.lastName}"`;
    const email = `"${user.email}"`;
    const role = user.role;
    const joined = formatDate(user.createdAt);
    return `${name},${email},${role},${joined}`;
  });

  const csv = [header, ...rows].join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'users.csv';
  link.click();
  URL.revokeObjectURL(url);
};

